import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Properties;
import java.util.UUID;

public class ConfiguredService {
    private static final Path CONFIG_PATH;
    private static final Properties GLOBAL_SETTINGS = new Properties();

    // 1. Static Initializer Block: Runs once when class is loaded
    static {
        System.out.println("[1] Static block: Initializing paths and loading config...");
        CONFIG_PATH = Paths.get(System.getProperty("user.home"), "app.properties");

        if (Files.exists(CONFIG_PATH)) {
            try (var reader = Files.newBufferedReader(CONFIG_PATH)) {
                GLOBAL_SETTINGS.load(reader);
            } catch (IOException e) {
                // Checked exceptions must be caught inside static blocks
                System.err.println("Failed to load config file. Using defaults. " + e.getMessage());
            }
        } else {
            System.out.println("Config file not found. Initializing with empty properties.");
        }
    }

    private final String instanceId;
    private final Path sessionLogPath;

    // 2. Instance Initializer Block: Runs for every object instantiation
    {
        System.out.println("[2] Instance block: Generating session ID and creating log file...");
        this.instanceId = UUID.randomUUID().toString();
        this.sessionLogPath = Paths.get(System.getProperty("java.io.tmpdir"), "session_" + instanceId + ".log");

        // This throws IOException. Therefore, ALL constructors MUST declare 'throws IOException'
        Files.createFile(this.sessionLogPath);
    }

    // 3. Constructor: Runs after instance initializers
    public ConfiguredService() throws IOException {
        System.out.println("[3] Constructor: Service successfully initialized for ID: " + instanceId);
    }

    // Overloaded Constructor: Must also declare the exception thrown by the instance block
    public ConfiguredService(String customMessage) throws IOException {
        this();
        System.out.println("[3] Overloaded Constructor: Custom Message: " + customMessage);
    }
}
